const fs = require("fs")
function clean(text) {
  const names = text.split(/\r?\n/).map((s) => s.trim()).filter(Boolean)
  return [...new Set(names)].sort().join("\n")
}
function scrub(input, output) {
  fs.writeFileSync(output, clean(fs.readFileSync(input, "utf8")))
}
scrub("messy.txt", "clean.txt")
console.log("ok")
module.exports = { clean, scrub }
